import 'dotenv/config';import bcrypt from 'bcryptjs';import {q,db} from './db.js';const email=process.env.BOOTSTRAP_ADMIN_EMAIL,password=process.env.BOOTSTRAP_ADMIN_PASSWORD;if(!email||!password||password.length<12)throw new Error('Configure BOOTSTRAP_ADMIN_EMAIL e BOOTSTRAP_ADMIN_PASSWORD de 12+ caracteres');try{const hash=await bcrypt.hash(password,12);const r=await q("INSERT INTO users(name,email,password_hash,role) VALUES('Administrador Master',$1,$2,'master') ON CONFLICT(email) DO NOTHING RETURNING id",[email.toLowerCase(),hash]);console.log(r.rowCount?'Master criado':'E-mail existente: nenhuma alteração');}finally{await db.end();}